import React, { useState, useEffect } from 'react';
import { FaHeart, FaHome, FaPlus, FaUser, FaSignOutAlt } from 'react-icons/fa';
import LoginSignup from './components/LoginSignup';
import Home from './pages/Home';
import Post from './pages/Post';
import Profile from './pages/Profile';
import './App.css';

function App() {
  const [currentUser, setCurrentUser] = useState(null);
  const [currentPage, setCurrentPage] = useState('home');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // Check if user is logged in (from localStorage)
    const savedUser = localStorage.getItem('currentUser');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
    }
  }, []);

  const handleLogin = (user) => {
    setCurrentUser(user);
    localStorage.setItem('currentUser', JSON.stringify(user));
  };

  const handleLogout = () => {
    setIsLoading(true);
    setTimeout(() => {
      setCurrentUser(null);
      localStorage.removeItem('currentUser');
      setCurrentPage('home');
      setIsLoading(false);
    }, 500);
  };

  const handlePageChange = (page) => {
    setIsLoading(true);
    setTimeout(() => {
      setCurrentPage(page);
      setIsLoading(false);
    }, 300);
  };

  const handleUserUpdate = (updatedUser) => {
    setCurrentUser(updatedUser);
    localStorage.setItem('currentUser', JSON.stringify(updatedUser));
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Home currentUser={currentUser} />;
      case 'post':
        return <Post currentUser={currentUser} />;
      case 'profile':
        return <Profile currentUser={currentUser} onUserUpdate={handleUserUpdate} />;
      default:
        return <Home currentUser={currentUser} />;
    }
  };

  if (!currentUser) {
    return <LoginSignup onLogin={handleLogin} />;
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="header-left">
          <FaHeart className="love-icon" />
          <h1>Social Media</h1>
        </div>
        <nav className="header-nav">
          <button
            className={currentPage === 'home' ? 'active' : ''}
            onClick={() => handlePageChange('home')}
            title="Home"
          >
            <FaHome />
          </button>
          <button
            className={currentPage === 'post' ? 'active' : ''}
            onClick={() => handlePageChange('post')}
            title="Post"
          >
            <FaPlus />
          </button>
          <button
            className={currentPage === 'profile' ? 'active' : ''}
            onClick={() => handlePageChange('profile')}
            title="Profile"
          >
            <FaUser />
          </button>
          <button onClick={handleLogout} title="Logout" disabled={isLoading}>
            <FaSignOutAlt />
          </button>
        </nav>
      </header>
      <main className={isLoading ? 'loading' : ''}>
        {renderPage()}
      </main>

      <footer className="app-footer">
        <div className="footer-content">
          <div className="footer-section">
            <h4>Social Media App</h4>
            <p>Connect, share, and discover amazing moments with people around the world.</p>
          </div>
          <div className="footer-section">
            <h4>Features</h4>
            <ul>
              <li>📸 Photo & Video Sharing</li>
              <li>👥 User Interactions</li>
              <li>🔍 Content Discovery</li>
              <li>📊 Analytics Dashboard</li>
            </ul>
          </div>
          <div className="footer-section">
            <h4>Support</h4>
            <ul>
              <li>📧 Help Center</li>
              <li>🛡️ Privacy Policy</li>
              <li>📋 Terms of Service</li>
              <li>📞 Contact Us</li>
            </ul>
          </div>
        </div>
        <div className="footer-bottom">
          <p>&copy; 2025 Social Media App. All rights reserved. Made with ❤️ for sharing moments.</p>
        </div>
      </footer>

      {isLoading && <div className="loading-overlay">Loading...</div>}
    </div>
  );
}

export default App;
